def solve(g):
    g=np.array(g); H,W=g.shape
    # find template: largest connected nonzero comp
    m=(g!=0).astype(int); lab,n=label(m)
    best=None
    for i in range(1,n+1):
        cs=np.argwhere(lab==i)
        h=max(cs[:,0])-min(cs[:,0])+1; w=max(cs[:,1])-min(cs[:,1])+1
        if best is None or (h*w)>best[0]: best=(h,w,i)
    ti=lab.max()
    cells=np.argwhere(lab==ti)
    r0,c0=min(cells[:,0]),min(cells[:,1])
    tmpl=g[r0:r0+best[0],c0:c0+best[1]]
    # palette: smallest comp; get its colors in reading order (by row then col)
    sm=(best[2]==max(range(1,n+1), key=lambda i:len(np.argwhere(lab==i))))
    # find comps sorted by size
    sizes=[(len(np.argwhere(lab==i)),i) for i in range(1,n+1)]
    sizes.sort()
    pi=sizes[-1][1]  # palette comp index
    palcells=np.argwhere(lab==pi)
    pal=sorted({int(g[r,c]) for r,c in palcells})  # dedupe
    # template color regions: group template rows into maximal runs per color
    def regions(mat):
        res=[]
        cur=None
        for r,row in enumerate(mat):
            for c,v in enumerate(row):
                if v!=0:
                    if cur is None or (r,cur[1][0])!=(r,c-1):
                        pass
        return res
    # simpler: scan template, record (start row,color,end row) per contiguous run of same color in row-major order
    def runs(mat):
        rs=[]; cr=mat.flatten().shape[0]; cc=mat.flatten().shape[1]
        flat=mat.flatten()
        st=None;col=None
        for k,v in enumerate(flat):
            if v!=0 and st is None:
                st=k;col=v
            elif v!=col:
                rs.append((st//cc,col,k//cc))
                st=k;col=v
        rs.append((st//cc,col))  # simplify: store first cell info
        return rs
    # just collect (firstrow,lastrow,color) runs row-wise
    def runsbbox(mat):
        R=[];mH,mW=mat.shape
        for r in range(mH):
            for c in range(mW):
                v=mat[r,c]
                if v==0: continue
                # run length in this row
                c2=c
                while c2<mW and mat[r,c2]==v: c2+=1
                R.append((r,c,c2-1,v))
        return R
    Rs=runsbbox(tmpl)
    # merge into color-bands: each band = set of consecutive rows containing that color
    bands={}
    for r,c2,v in Rs:
        for rr in range(r,c2+1):
            bands.setdefault(rr,set()).add(v)
    # simplify: each color's extent in template
    ext={}
    for (r,c2,v) in Rs:
        ext[v]=(min(ext.get(v,(10**9))),max(c2))
    # determine stack height per color: use max band height? In demo2 all 3. Use template region extents:
    hext={}
    for (r,c2,v) in Rs:
        extv=hext.get(v)
        if extv is None: extv=[r,r]
        else: extv[1]=max(extv[1],c2)
        # convert to rows: use first row and last row per color across template
    hext={}
    for r,c2,v in Rs:
        hext.setdefault(v,[r,r])[1]=max(hext[v][1],c2)
    # band height per color = (last_row-first_row+1) per color in template
    bandh={}
    for v,(fr,lr) in hext.items():
        bandh[v]=lr-fr+1
    porder=pal  # colors in palette order = sorted order here (palette read left-to-right)
    # palette indices: position of each color
    pos={v:i for i,v in enumerate(porder)}
    # template colors present
    tc=set(v for _ in Rs for v in [_.v] if False)
    tc={v for v,_ in [Rs]}
    # origin: template top minus (number of palette colors before any template color)*? Use demo-consistent: 
    # stack contiguous in palette order; template occupies its own slot(s).
    tcolors=pos & set(bandh)
    minpos=min(pos[t] for t in tcolors)
    origin=r0 - minpos*bandh.get(next(iter(tcolors)),0) if tcolors else r0
    out=np.zeros_like(g)
    for i,v in enumerate(porder):
        hh=bandh.get(v,3)
        rr=origin+i*hh
        out[rr:rr+hh,c0:c0+tmpl.shape[1]]= tmpl[:hh,:]*np.ones((hh,tmpl.shape[1])) if False else None
        out[rr:rr+hh,c0:c0+tmpl.shape[1]] = np.where(tmpl[:hh,:]!=0, v, 0)
    glist=[[int(x) for x in r] for r in out.tolist()]
    return glist

